function applySite(d){
 var map=function(x){return{iso:x.item_date,t:[x.title_rw,x.title_en||x.title_rw],p:[x.body_rw,x.body_en||x.body_rw]}};
 NEWS=(d.news||[]).map(map);EVENTS=(d.events||[]).map(map);CONTACT=d.contact||{};
 var c=CONTACT,rw=[],en=[];
 if(c.phone){rw.push("Telefoni: "+c.phone);en.push("Phone: "+c.phone)}
 if(c.email){rw.push("Imeri: "+c.email);en.push("Email: "+c.email)}
 if(c.address){rw.push("Aho turi: "+c.address);en.push("Location: "+c.address)}
 if(c.hours){rw.push("Amasaha yo gusura: "+c.hours);en.push("Visiting hours: "+c.hours)}
 UI.rw.ct=rw.join(" · ");UI.en.ct=en.join(" · ");
 var wa=document.getElementById("wa");if(wa){var dg=String(c.whatsapp||"").replace(/\D/g,"");if(dg){wa.href="https://wa.me/"+dg}else wa.removeAttribute("href")}
 render();
}
function syncSite(){
 var show=function(id,on){var e=document.getElementById(id);if(e)e.hidden=!on};
 show("amakuru",NEWS.length);show("ibikorwa",EVENTS.length);
 [].forEach.call(document.querySelectorAll('nav a[href="#amakuru"]'),function(a){a.hidden=!NEWS.length});
 [].forEach.call(document.querySelectorAll('nav a[href="#ibikorwa"]'),function(a){a.hidden=!EVENTS.length});
 var ct=document.getElementById("ctline");if(ct)ct.hidden=!UI[L].ct;
 var wa=document.getElementById("wa");if(wa)wa.hidden=!wa.getAttribute("href");
}
